/// <summary>
/// The <c>METSalesOrderLoadPlanningAidController</c> class is the helper class for the associated SRS Report.
/// </summary>
class METSalesOrderLoadPlanningAidController extends SrsPrintMgmtFormLetterController
{
    CustInvoiceTable custInvoiceTable;
    METSalesOrderLoadPlanningAidContract salesLoadPlanningAidContract;
}

Method.Source:
public static METSalesOrderLoadPlanningAidController construct()
{
    return new METSalesOrderLoadPlanningAidController();
}

/// <summary>
/// Initailzes the controller, sets the print management, assigns parameter values and runs the SRS report.
/// </summary>
/// <param name="_args">
/// The <c>Args</c> object.
/// </param>
public static void main(Args _args)
{
    SrsPrintMgmtController controller = METSalesOrderLoadPlanningAidController::construct();

    controller.parmReportName(PrintMgmtDocType::construct(PrintMgmtDocumentType::METCustActivityStatement).getDefaultReportFormat());
    controller.parmArgs(_args);
    controller.parmDialogCaption("Load planning aid");
    controller.startOperation();
}

protected void initPrintMgmtReportRun(PrintMgmtDocumentType _printMgmtDocumentType = PrintMgmtDocumentType::METCustActivityStatement)
{
    printMgmtReportRun = printMgmtReportRun::construct( PrintMgmtHierarchyType::Sales,
                                                        PrintMgmtNodeType::Sales,
                                                        _printMgmtDocumentType);

    printMgmtReportRun.parmReportRunController(this);

    super();
}

/// <summary>
/// Initializes the report and sets the print management.
/// </summary>
protected void initFormLetterReport()
{
    formLetterReport = FormLetterReport::construct(PrintMgmtDocumentType::METCustActivityStatement);
    formLetterReport.parmUsePrintMgmtDestinations(salesLoadPlanningAidContract.parmUsePrintManagement());
}

/// <summary>
///    Changes the report contract before the report is run.
/// </summary>
protected void preRunModifyContract()
{
    salesLoadPlanningAidContract = this.parmReportContract().parmRdpContract();
    salesLoadPlanningAidContract.parmConfirmedShipDateFrom(DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()));
    salesLoadPlanningAidContract.parmConfirmedShipDateTo(DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()));
}

/// <summary>
/// Gets the Contract class.
/// </summary>
/// <returns>Contract class </returns>
protected METSalesOrderLoadPlanningAidContract parmContract()
{
    if (!salesLoadPlanningAidContract)
    {
        salesLoadPlanningAidContract = this.parmReportContract().parmRdpContract() as METSalesOrderLoadPlanningAidContract;
    }
    return salesLoadPlanningAidContract;
}
